"); dump(TMP,B, "tmp = B+1;
"); dump(CC, TMP, "CC = (tmp>>8)&1;
"); dump(B, TMP, "B = tmp&255;
"); dump(Always, Always, " // INC B
"); dump(PC, 0, "PC = 0xA004;
"); dump(TMP,B, "tmp = B+1;
"); dump(CC, TMP, "CC = (tmp>>8)&1;
"); dump(B, TMP, "B = tmp&255;
"); dump(Always, Always, " // ASR A,B
"); dump(PC, 0, "PC = 0xA005;
"); dump(A, B, "A = B>>1;
"); dump(Always, Always, " // LDB #1
"); dump(PC, 0, "PC = 0xA006;
"); dump(B, 0, "B = 1;
"); dump(Always, Always, " // JMP 0xFC08
"); dump(PC, 0, "PC = 0xA008;
"); dump(Always, Always, "
